      "name": "Nat.mul_sub_div_of_dvd",
      "type": " {b c : ℕ} (hc : c ≠ 0) (hcb : c ∣ b) (a : ℕ) : (c * a - b) / c = a - b / c",
      "module": "Init.Data.Nat.Lemmas"
    },
    {
      "name": "Nat.mul_sub_mul_div_of_dvd",
      "type": " {b d a c : ℕ} (hb : b ≠ 0) (hd : d ≠ 0) (hba : b ∣ a) (hdc : d ∣ c) : (a * d - b * c) / (b * d) = a / b - c / d",
      "module": "Init.Data.Nat.Lemmas"
    },
    {
      "name": "Int.sub_ediv_of_dvd_sub",
      "type": " {a b c : ℤ} (hcab : c ∣ a - b) : (a - b) / c = a / c - b / c",
      "module": "Init.Data.Int.DivMod.Lemmas"
    },
    {
      "name": "BitVec.getLsbD_flattenList",
      "type": " {w : ℕ} (vs : List (BitVec w)) (i : ℕ) : (BitVec.flattenList vs).getLsbD i = (decide (i < w * vs.length) && (vs[vs.length - 1 - i / w]?.getD 0#w).getLsbD (i % w))",
      "module": "Init.Data.BitVec.Lemmas"
    },
    {
      "name": "BitVec.extractLsb_flattenList",
      "type": " (hi lo : ℕ) {w : ℕ} (vs : List (BitVec w)) (w₁ : lo ≤ hi) (w₂ : hi < w * vs.length) (h : hi / w = lo / w) : BitVec.extractLsb hi lo (BitVec.flattenList vs) = BitVec.cast ⋯ (BitVec.extractLsb (hi % w) (lo % w) (vs[vs.length - 1 - hi / w]?.getD 0#w))",
      "module": "Init.Data.BitVec.Lemmas"
    }
  ]
